import{bQ as e,aL as t,u as r,G as o}from"./chunks/framework.DaEK0KQB.js";const _=JSON.parse('{"title":"广告方面专业术语","description":"","frontmatter":{"title":"广告方面专业术语","date":"2023-09-08T13:37:26.000Z","permalink":"/pages/a98d55/","categories":["更多","学习"],"tags":[null]},"headers":[],"relativePath":"更多/学习/06.广告方面专业术语.md","filePath":"更多/学习/06.广告方面专业术语.md","lastUpdated":1785225860000}'),c={name:"更多/学习/06.广告方面专业术语.md"};function i(l,a,n,s,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="广告方面专业术语" tabindex="-1">广告方面专业术语 <a class="header-anchor" href="#广告方面专业术语" aria-label="Permalink to &quot;广告方面专业术语&quot;">​</a></h1><h3 id="专业名词" tabindex="-1">专业名词 <a class="header-anchor" href="#专业名词" aria-label="Permalink to &quot;专业名词&quot;">​</a></h3><h4 id="cpc" tabindex="-1">CPC <a class="header-anchor" href="#cpc" aria-label="Permalink to &quot;CPC&quot;">​</a></h4><p>CPC是一种按点击付费的互联网广告广告形式，具体来说，就是广告主在使用cpc计费的广告平台上投放广告，广告平台将按照该广告被点击一次收取一次费用，广告展示则不收取费用。</p><h4 id="cpm" tabindex="-1">CPM <a class="header-anchor" href="#cpm" aria-label="Permalink to &quot;CPM&quot;">​</a></h4><p>CPM指的是按展示付费的广告，比如说一个内置广告横幅的单价是1元/CPM的话，意味着每一千人次看到这个广告就收1元起，以此类推，10000人次访问的主页就是10元。</p><h4 id="ocpc" tabindex="-1">OCPC <a class="header-anchor" href="#ocpc" aria-label="Permalink to &quot;OCPC&quot;">​</a></h4><p>OCPC是一种广告竞价方式，全称为On-Click Programmatic Conversion，即“按点击计费的自动化转化广告购买模式”。和传统的CPC（按点击计费）和CPA（按转化计费）广告购买模式不同，OCPC结合了两者的优势，通过广告投放数据和算法，实现对具有转化潜力的流量进行自动化的出价和优化，以实现更高的广告投放效果和ROI。</p><h4 id="cpa" tabindex="-1">CPA <a class="header-anchor" href="#cpa" aria-label="Permalink to &quot;CPA&quot;">​</a></h4><p>CPA是按行动付费，是通过推广之后的用户行为进行收费，投放广告之后按照订单数量等方式进行统计。</p>',10)])])}const C=e(c,[["render",i]]);export{_ as __pageData,C as default};
